// Summarize the share-of-voice trend into facts for the LLM.
const body = $input.first().json;
const points = (body.points || []).filter((p) => p.total_mentions > 0);
if (points.length === 0) {
  return [{ target_brand: body.target_brand, has_data: false }];
}
const latest = points[points.length - 1];
const previous = points.length > 1 ? points[points.length - 2] : null;
const competitors = latest.competitor_mentions || {};
const topCompetitor = Object.entries(competitors).sort((a, b) => b[1] - a[1])[0];
return [{
  target_brand: body.target_brand,
  has_data: true,
  latest_share: latest.share,
  latest_run_id: latest.run_id,
  previous_share: previous ? previous.share : null,
  delta_pp: previous && previous.share !== null && latest.share !== null
    ? Math.round((latest.share - previous.share) * 100) / 100
    : null,
  top_competitor: topCompetitor ? topCompetitor[0] : null,
  top_competitor_mentions: topCompetitor ? topCompetitor[1] : 0,
  runs_in_window: points.length
}];
